import math
import sys

def read_input():
    x1, y1, x2, y2 = map(int, sys.stdin.readline().strip().split())
    v, t = map(int, sys.stdin.readline().strip().split())
    wx1, wy1 = map(int, sys.stdin.readline().strip().split())
    wx2, wy2 = map(int, sys.stdin.readline().strip().split())
    return (x1, y1, x2, y2, v, t, (wx1, wy1), (wx2, wy2))

def distance(x1, y1, x2, y2):
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

def minimum_time_to_reach(x1, y1, x2, y2, v, t, wind1, wind2):
    d = distance(x1, y1, x2, y2)

    # Time with wind1 for t seconds, then calculate time with wind2
    time_with_wind1 = (d - (wind1[0] * t)) / (v + wind1[0])
    time_with_wind1 = max(time_with_wind1, 0)  # Cannot be negative
    total_time1 = t + time_with_wind1

    # Time only with wind2
    total_time2 = d / (v + wind2[0])

    return min(total_time1, total_time2)

def main():
    x1, y1, x2, y2, v, t, wind1, wind2 = read_input()
    result = minimum_time_to_reach(x1, y1, x2, y2, v, t, wind1, wind2)
    print(f'{result:.10f}')

if __name__ == "__main__":
    main()

