def count_painted_cells(n, segments):
    from collections import defaultdict

    horizontal_segments = defaultdict(list)
    vertical_segments = defaultdict(list)

    for x1, y1, x2, y2 in segments:
        if y1 == y2:  # Horizontal segment
            if x1 > x2:
                x1, x2 = x2, x1
            horizontal_segments[y1].append((x1, x2))
        elif x1 == x2:  # Vertical segment
            if y1 > y2:
                y1, y2 = y2, y1
            vertical_segments[x1].append((y1, y2))

    painted_cells = set()

    # Process horizontal segments
    for y, ranges in horizontal_segments.items():
        merged_ranges = []
        for start, end in sorted(ranges):
            if not merged_ranges or merged_ranges[-1][1] < start:
                merged_ranges.append((start, end))
            else:
                merged_ranges[-1] = (merged_ranges[-1][0], max(merged_ranges[-1][1], end))

        for start, end in merged_ranges:
            for x in range(start, end + 1):
                painted_cells.add((x, y))

    # Process vertical segments
    for x, ranges in vertical_segments.items():
        merged_ranges = []
        for start, end in sorted(ranges):
            if not merged_ranges or merged_ranges[-1][1] < start:
                merged_ranges.append((start, end))
            else:
                merged_ranges[-1] = (merged_ranges[-1][0], max(merged_ranges[-1][1], end))

        for start, end in merged_ranges:
            for y in range(start, end + 1):
                painted_cells.add((x, y))

    return len(painted_cells)

