def count_painted_cells(n, segments):
    from collections import defaultdict

    horizontal_segments = defaultdict(set)
    vertical_segments = defaultdict(set)

    for x1, y1, x2, y2 in segments:
        if y1 == y2:  # horizontal segment
            x1, x2 = min(x1, x2), max(x1, x2)
            for x in range(x1, x2):
                horizontal_segments[y1].add(x)
        else:  # vertical segment
            y1, y2 = min(y1, y2), max(y1, y2)
            for y in range(y1, y2):
                vertical_segments[x1].add(y)

    painted_cells = set()

    for y, xs in horizontal_segments.items():
        for x in xs:
            painted_cells.add((x, y))

    for x, ys in vertical_segments.items():
        for y in ys:
            painted_cells.add((x, y))

    return len(painted_cells)

