        for i in range(s_len):
            if start + i >= t_len:
                return False
            if s[i][1] != t[start + i][1]:
                return False
            if s[i][0] > t[start + i][0]:
                return False
            if s[i][0] < t[start + i][0]:
                t[start + i] = (t[start + i][0] - s[i][0], t[start + i][1])
                break
        return True

    occurrences = 0
    for i in range(t_len):
        if check_occurrence(i):
            occurrences += 1
            for j in range(s_len):
                if i + j < t_len:
                    t[i + j] = (t[i + j][0] - s[j][0], t[i + j][1]) 
                else:
