def bear_and_two_paths(n, k, a, b, c, d):
    if k < n - 1 or k > 2 * n - 2:
        return -1

    other_cities = []
    for i in range(1, n + 1):
        if i not in (a, b, c, d):
            other_cities.append(i)

    if len(other_cities) < n - 4:
        return -1

    v_path = [a] + other_cities[:n - 2] + [b]
    u_path = [c] + other_cities[n - 2:] + [d]

    roads = set()
    for i in range(n - 1):
        roads.add((v_path[i], v_path[i + 1]))
        roads.add((u_path[i], u_path[i + 1]))

    if len(roads) > k:
        return -1

    return v_path, u_path

