def rebus_solver(equation):
    equation = equation.replace('=', ' =').strip()
    left_side, right_side = equation.split(' = ')
    n = int(right_side.strip())

    left_terms = left_side.split()
    if left_terms.count('?') == 0:
        return 'Impossible'

    operations = left_terms[1::2]
    question_marks = [i for i, term in enumerate(left_terms) if term == '?']

    # We will generate all possible combinations of numbers for '?'
    for values in product(range(1, n + 1), repeat=len(question_marks)):
        for idx, value in zip(question_marks, values):
            left_terms[idx] = str(value)
        left_expression = ''.join(left_terms)
        if eval(left_expression.replace('+', ' + ').replace('-', ' - ')) == n:
            return 'Possible\n' + left_expression + ' = ' + str(n)

    return 'Impossible'

