def replace_question_marks(rebus, n):
    parts = rebus.split()
    question_marks = parts.count('?')

    if parts[0] == '?' and len(parts) == 3 and parts[1] == '=':
        return f"Possible{n} = {n}"

    total_rhs = n
    total_lhs = 0
    sign = 1  # +1 for '+', -1 for '-'

    numbers = []

    for part in parts:
        if part == '?':
            numbers.append('?')
        elif part == '+':
            sign = 1
        elif part == '-':
            sign = -1
        elif part == '=':
            continue
        else:
            total_lhs += sign * int(part)
            total_rhs += sign * int(part)

    needed = total_rhs - total_lhs

    if needed < question_marks or needed > question_marks * n:
        return "Impossible"

    values = []
    for i in range(question_marks):
        if needed > n:
            values.append(n)
            needed -= n
        else:
            values.append(needed)
            needed = 0

    result = []
    value_index = 0

    for part in parts:
        if part == '?':
            result.append(str(values[value_index]))
            value_index += 1
        else:
            result.append(part)

