def find_smallest_t(n, crushes):
    # Create a function to determine the round depth for each person
    def get_depth(start, t):
        visited = {}
        current = start
        depth = 0
        while current not in visited and depth < t:
            visited[current] = depth
            current = crushes[current - 1]
            depth += 1
        return depth

