def can_form_rectangle(n, m, grid):
    # Finding the bounds of the 'X's
    min_row, max_row = n, -1
    min_col, max_col = m, -1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                if i < min_row:
                    min_row = i
                if i > max_row:
                    max_row = i
                if j < min_col:
                    min_col = j
                if j > max_col:
                    max_col = j

    # Calculate the area of the filled rectangle
    area_filled = (max_row - min_row + 1) * (max_col - min_col + 1)

    # Count number of 'X's in the original grid
    count_x = sum(row.count('X') for row in grid)

    # If the area filled matches the count of 'X's, we can form a rectangle
    if area_filled == 2 * count_x:
        return "YES"
    else:
        return "NO"

