    special_chars = {'#', '*', '&'}

    # Function to compute the minimum moves for each character in the string
    def min_moves(s, target):
        m = len(s)
        for i in range(m):
            if s[i] == target:
                return min(i, m - i)
        return m  # shouldn't happen given the problem constraints

