    for s in strings:
        digit_moves = min_moves(s, '0')  # Start with digit moves
        lower_moves = min_moves(s, 'a')  # Start with lower moves 
        special_moves = min(min_moves(s, char) for char in special_chars)  # Start with special moves

        operations.append((digit_moves, lower_moves, special_moves))

        # Check types available in the current string
        if any(c.isdigit() for c in s):
            has_digit = True
        if any(c.islower() for c in s):
            has_lower = True
        if any(c in special_chars for c in s):
            has_special = True

    # Base case checks (if we already have all types)
    if has_digit and has_lower and has_special:
        return 0

    # Find minimum extra operations required to complete the password
    min_extra_operations = float('inf')

