    for i in range(n):
        if not has_digit:
            min_extra_operations = min(min_extra_operations, operations[i][0])
        if not has_lower:
            min_extra_operations = min(min_extra_operations, operations[i][1])
        if not has_special:
            min_extra_operations = min(min_extra_operations, operations[i][2])

