def probability_of_teammate(n, m, h, departments):
    s_h = departments[h - 1]
    total_students = sum(departments)

    if total_students < n:
        return -1

    if s_h == 1 or (total_students - 1) < (n - 1):
        return 0.0

    # Total teams including Herr Wafa
    total_teams = 0
    teams_without_h_department = 0

    for i in range(max(0, n - 1), min(departments[h - 1], n) + 1):
        players_from_h = i
        remaining_players = n - 1 - players_from_h

        if remaining_players > total_students - s_h:
            continue

        total_teams += comb(s_h - 1, players_from_h - 1) * comb(total_students - s_h, remaining_players)

    for i in range(max(0, n - 1), min(departments[h - 1] - 1, n) + 1):
        players_from_h = i
        remaining_players = n - 1 - players_from_h

        if remaining_players > total_students - s_h:
            continue

        teams_without_h_department += comb(total_students - s_h, remaining_players)

    return 1 - (teams_without_h_department / total_teams)

