def count_possible_locations(n, movements):
    # Create movement vectors for each possible direction
    move_options = {
        'UL': [(-1, 1), (0, 0)],
        'UR': [(1, 1), (0, 0)],
        'DL': [(-1, -1), (0, 0)],
        'DR': [(1, -1), (0, 0)],
        'ULDR': [(-1, 1), (1, 1), (-1, -1), (1, -1)]
    }

    # Set to track unique positions
    positions = {(0, 0)}

    for movement in movements:
        current_positions = set()
        for dx, dy in move_options[movement]:
            for x, y in positions:
                current_positions.add((x + dx, y + dy))
        positions = current_positions

    return len(positions)

