def find_strings(h):
    from itertools import combinations
    from collections import defaultdict

    h = list(map(int, h.split()))
    h_matrix = [
        [0, h[0], h[1], h[2]],
        [h[0], 0, h[3], h[4]],
        [h[1], h[3], 0, h[5]],
        [h[2], h[4], h[5], 0]
    ]

    def backtrack(idx, path):
        if idx == 4:
            return path
        for bits in range(1 << idx):
            strings = []
            for i in range(4):
                if (bits >> i) & 1:
                    strings.append('a')
                else:
                    strings.append('b')
            dist = sum((strings[i] != strings[j]) for i in range(idx + 1) for j in range(i + 1, idx + 1))
            if dist == h_matrix[idx]:
                new_path = backtrack(idx + 1, path + [''.join(strings)])
                if new_path:
