        size = 1
        component_sizes = []

        for neighbor in tree[node]:
            if neighbor == parent:
                continue
            subtree_size = dfs(neighbor, node)
            component_sizes.append(subtree_size)
            size += subtree_size

        if parent != -1 and len(component_sizes) > 0:
            component_sizes.append(n - size)

        for i in component_sizes:
            for j in component_sizes:
                if i != j:
                    max_product = max(max_product, i * j)

        return size

