def expected_score(n, p):
    expected = 0.0
    for i in range(n):
        current_prob = p[i]
        if i > 0:
            previous_prob = 1 - p[i-1]
            expected += current_prob * current_prob * (1 - previous_prob) * (1 + 2 * sum(p[j] for j in range(i)))
        else:
            expected += current_prob * current_prob * (1 - p[i])
    if n > 1:
        for i in range(1, n):
            expected += (1 - p[i-1]) * p[i] * (i + 1)
    return expected

