def count_non_wool_sequences(n, m):
    mod = 1000000009
    total_sequences = pow(2**m, n, mod)
    non_wool_sequences = total_sequences

    for i in range(m + 1):
        if i > 0:
            non_wool_sequences -= pow(2**(m - i), n, mod) * comb(m, i) % mod
            non_wool_sequences %= mod

    return non_wool_sequences

def comb(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    num = den = 1
    for i in range(k):
        num = (num * (n - i)) % 1000000009
        den = (den * (i + 1)) % 1000000009
    return (num * pow(den, 1000000009 - 2, 1000000009)) % 1000000009

