    if (n * m) % 2 != 0:
        return "IMPOSSIBLE"  # Odd area cannot be fully covered

    grid = [['.'] * m for _ in range(n)]
    planks = []
    char = 'a'

    # Place 2x2 planks first
    for i in range(n - 1):
        for j in range(m - 1):
            if c > 0:
                grid[i][j] = grid[i][j + 1] = grid[i + 1][j] = grid[i + 1][j + 1] = char
                c -= 1
                char = chr(ord(char) + 1) if char < 'z' else char

    # Place 1x2 planks
    for i in range(n):
        for j in range(m - 1):
            if grid[i][j] == '.' and a > 0:
                grid[i][j] = grid[i][j + 1] = char
                a -= 1
                char = chr(ord(char) + 1) if char < 'z' else char

