    from itertools import product
    import math

    def count_divisors(factors):
        count = 1
        for power in factors:
            count *= (power + 1)
        return count

    def generate_factors(max_value):
        prime = []
        is_prime = [True] * (max_value + 1)
        for i in range(2, max_value + 1):
            if is_prime[i]:
                prime.append(i)
                for j in range(i * 2, max_value + 1, i):
                    is_prime[j] = False
        return prime

    primes = generate_factors(100)
    min_number = None

    for k in range(1, 15):  # The maximum number of primes to consider
        for powers in product(range(15), repeat=k):
            if count_divisors(powers) == n:
                number = 1
                for i in range(k):
                    if powers[i] > 0:
                        number *= primes[i] ** powers[i]
                if number <= 10**18:
                    if min_number is None or number < min_number:
                        min_number = number
    return min_number

