def smallest_box(n, sizes):
    from collections import defaultdict
    count = defaultdict(int)

    for k, a in sizes:
        count[k] += a

    max_count = 0
    for k in sorted(count.keys()):
        max_count = max(max_count, count[k])
        if max_count > 4:
            max_count = (max_count + 3) // 4  # Ceil division
            if max_count > 1:
                max_count = 1

    result = 0
    while max_count > 0:
        max_count = (max_count + 3) // 4  # Ceil division
        result += 1

    return result

