def smallest_magical_box(n, sizes):
    from collections import defaultdict

    count = defaultdict(int)

    for k, a in sizes:
        count[k] += a

    total_boxes = sum(count.values())

    def get_minimum_box_size(total):
        p = 0
        while (1 << p) < total:
            p += 1
        return p

    p = get_minimum_box_size(total_boxes)

    for k in sorted(count.keys()):
        while count[k] > 0:
            if k + 1 in count:
                count[k + 1] += count[k] // 4
                count[k] %= 4
            else:
                p = max(p, k)
                break
            k += 1

    return p


