def least_cost_bracket_sequence(pattern, costs):
    n = len(pattern)
    m = sum(1 for ch in pattern if ch == '?')

    if n % 2 != 0 or m * 2 < n - pattern.count('(') - pattern.count(')'):
        return -1, ""

    required_open = (n // 2) - pattern.count('(')
    required_close = (n // 2) - pattern.count(')')

    if required_open < 0 or required_close < 0:
        return -1, ""

    total_cost = 0
    sequence = list(pattern)
    cost_index = 0

    for i in range(n):
        if sequence[i] == '?':
            if required_open > 0:
                total_cost += costs[cost_index][0]  # cost of '('
                sequence[i] = '('
                required_open -= 1
            else:
                total_cost += costs[cost_index][1]  # cost of ')'
                sequence[i] = ')'
            cost_index += 1

    # Validate the final sequence
    balance = 0
    for ch in sequence:
        if ch == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return -1, ""

    return total_cost, ''.join(sequence)

