def least_cost_bracket_sequence(pattern, costs):
    n = len(pattern)
    m = pattern.count('?')

    # cost of replacing each '?' with '(' or ')'
    cost_map = {i: costs[i] for i in range(m)}

    # dp[i][j] = min cost to have a valid sequence using first i characters and j '(' left to match
    inf = float('inf')
    dp = [[inf] * (n // 2 + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    # To reconstruct the sequence
    sequence = [[''] * (n // 2 + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(n // 2 + 1):
            if dp[i][j] == inf:
                continue

            if pattern[i] == '(':
                dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i][j])
                sequence[i + 1][j + 1] = sequence[i][j] + '('
            elif pattern[i] == ')':
                if j > 0:
                    dp[i + 1][j - 1] = min(dp[i + 1][j - 1], dp[i][j])
                    sequence[i + 1][j - 1] = sequence[i][j] + ')'
            else:
                # For '?', we try both options
                if j < n // 2:
                    dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i][j] + cost_map[i])
                    sequence[i + 1][j + 1] = sequence[i][j] + '('
                if j > 0:
                    dp[i + 1][j - 1] = min(dp[i + 1][j - 1], dp[i][j] + cost_map[i])
                    sequence[i + 1][j - 1] = sequence[i][j] + ')'

    result_cost = dp[n][0]
    if result_cost == inf:
        return -1, ""
    else:
        return result_cost, sequence[n][0]


