def find_segment(n, arr):
    orig = list(range(1, n + 1))

    left = 0
    while left < n and arr[left] == orig[left]:
        left += 1

    if left == n:  # Already sorted
        return (0, 0)

    right = n - 1
    while right >= 0 and arr[right] == orig[right]:
        right -= 1

    if right <= left:  # No valid segment
        return (0, 0)

    # Check if reversing the segment gives the original array
    reversed_segment = arr[left:right + 1][::-1]
    if orig[left:right + 1] == reversed_segment:
        return (left + 1, right + 1)  # +1 for 1-based indexing

    return (0, 0)


