    total_liking = 0
    for team in teams:
        for p in team:
            for q in team:
                if p != q and (p, q) in likes:
                    total_liking += 1
    return total_liking

def min_max_diff_teams(n, likes, exp):
    roles = [0, 1, 2, 3, 4, 5, 6] # Representing 7 heroes
    min_diff = float('inf')
    max_liking = 0
    total_exp = exp[0] + exp[1] + exp[2]

    for team1 in combinations(roles, 3):
        rem = list(set(roles) - set(team1))
        for team2 in combinations(rem, 2):
            team3 = list(set(rem) - set(team2))
            teams = [team1, team2, team3]
            exp_values = [exp[0] // len(team1), exp[1] // len(team2), exp[2] // len(team3)]
            current_diff = max(exp_values) - min(exp_values)
            if current_diff < min_diff:
                min_diff = current_diff
                max_liking = compute_liking(teams, likes)
            elif current_diff == min_diff:
                max_liking = max(max_liking, compute_liking(teams, likes))

    return min_diff, max_liking

def main():
    import sys
    input = sys.stdin.read
    data = input().strip().split('\n')

    n = int(data[0])
    likes = set()

    for i in range(1, n + 1):
        p, _, q = data[i].partition(' likes ')
        likes.add((int(p[-1]), int(q[-1])))

    exp = list(map(int, data[n + 1].split()))
    result = min_max_diff_teams(n, likes, exp)

    print(result[0], result[1])

if __name__ == "__main__":
    main()

