def count_combinations(n):
    from math import comb

    count = 0
    for r in range(n // 2 + 1):
        count += comb(n, r)

    return count

def generate_bead_string(n, index):
    if index < 1:
        return -1

    beads = []
    count = count_combinations(n)

    if index > count:
        return -1

    for r in range(n // 2 + 1):
        combinations = count_combinations(n - 2 * r)
        if index <= combinations:
            beads = [0] * r + [1] * (n - r)
            beads = sorted(beads)
            break
        index -= combinations

    return ''.join(map(str, beads))

