def african_crossword(n, m, grid):
    from collections import defaultdict

    row_counts = [defaultdict(int) for _ in range(n)]
    col_counts = [defaultdict(int) for _ in range(m)]

    # Count occurrences of each letter in each row and column
    for r in range(n):
        for c in range(m):
            letter = grid[r][c]
            row_counts[r][letter] += 1
            col_counts[c][letter] += 1

    result = []
