from math import factorial

def count_decorations(colors):
    # Count the occurrences of each color
    color_count = {}
    for color in colors:
        if color in color_count:
            color_count[color] += 1
        else:
            color_count[color] = 1

    # Calculate the number of unique arrangements
    total_gems = sum(color_count.values())
    arrangements = factorial(total_gems)

    for count in color_count.values():
        arrangements //= factorial(count)

    return arrangements

def count_rotational_arrangements(colors):
    # Count decorations without considering rotations using Burnside's lemma
    n = len(colors)
    unique_decorations = 0

    for rotation in range(n):
        # Create an arrangement after rotation
        rotated = [colors[(i + rotation) % n] for i in range(n)]
        # Count distinct arrangements for this rotation
        color_count = {}
        for color in rotated:
            if color in color_count:
                color_count[color] += 1
            else:
                color_count[color] = 1

        arrangements = factorial(n)
        for count in color_count.values():
            arrangements //= factorial(count)

        unique_decorations += arrangements

    return unique_decorations // n

