def max_height_of_tower(rings):
    # Sort the rings by outer radius in descending order, and by inner radius in ascending order
    rings.sort(key=lambda x: (-x[1], x[0]))

    heights = []

    # Dynamic programming to find the maximum height
    for a, b, h in rings:
        # Find the position to insert this height (to keep track of the max heights)
        pos = len(heights)
        for i in range(len(heights)):
            if heights[i][0] <= a:
                pos = i
                break

        # If it's possible to place it on the tower
        if pos == len(heights):
            heights.append((b, h))  # (outer radius, current height)
        else:
            if h > heights[pos][1]:
                heights[pos] = (b, h)

    return sum(h for _, h in heights)

