def count_ways(n, m):
    MOD = 10**9 + 7

    # Base cases
    if m == 0:
        return 1
    if n == 0:
        return 0

    # Use dynamic programming to find the number of ways
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(n + 1):
        for j in range(m + 1):
            if i > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD

    return dp[n][m] * pow(2, m, MOD) % MOD

n, m = map(int, input().split())
print(count_ways(n, m))

